package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.parseOctal specifically designed to maximize branch and line coverage.
 */
public class TarUtils_parseOctal_TriageGen0Test {

    @Test
    public void testParseOctal_MinimumLengthException() {
        byte[] buffer = new byte[1];
        try {
            TarUtils.parseOctal(buffer, 0, 1);
            fail("Expected IllegalArgumentException for length < 2");
        } catch (IllegalArgumentException e) {
            assertEquals("Length 1 must be at least 2", e.getMessage());
        }
    }

    @Test
    public void testParseOctal_LeadingZeroBuffer() {
        byte[] buffer = new byte[5];
        buffer[0] = 0;
        // If buffer[start] is 0, it returns 0L immediately
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 4));
    }

    @Test
    public void testParseOctal_SimpleOctal() {
        // "755" in octal
        byte[] buffer = "755".getBytes();
        // We need to ensure buffer[end+1] is accessible to avoid IndexOutOfBounds
        // The logic uses buffer[end + 1] to check trailer
        byte[] extendedBuffer = new byte[10];
        System.arraycopy(buffer, 0, extendedBuffer, 0, buffer.length);
        extendedBuffer[buffer.length + 1] = 0; // trailer

        assertEquals(493L, TarUtils.parseOctal(extendedBuffer, 0, 3));
    }

    @Test
    public void testParseOctal_WithLeadingSpaces() {
        // "  123"
        byte[] buffer = "  123".getBytes();
        byte[] extendedBuffer = new byte[10];
        System.arraycopy(buffer, 0, extendedBuffer, 0, buffer.length);
        extendedBuffer[buffer.length + 1] = ' '; // trailer

        assertEquals(83L, TarUtils.parseOctal(extendedBuffer, 0, 5));
    }

    @Test
    public void testParseOctal_WithTrailingSpacesAndNuls() {
        // "123  \0"
        byte[] buffer = "123  ".getBytes();
        byte[] extendedBuffer = new byte[10];
        System.arraycopy(buffer, 0, extendedBuffer, 0, buffer.length);
        extendedBuffer[buffer.length + 1] = 0; // trailer

        // The logic: trailer = buffer[end+1]. If trailer is 0 or ' ', end--.
        // It trims trailing spaces/nuls.
        assertEquals(83L, TarUtils.parseOctal(extendedBuffer, 0, 5));
    }

    @Test
    public void testParseOctal_InvalidDigit() {
        // "128" (8 is not octal)
        byte[] buffer = "128".getBytes();
        byte[] extendedBuffer = new byte[10];
        System.arraycopy(buffer, 0, extendedBuffer, 0, buffer.length);
        extendedBuffer[buffer.length + 1] = 0;

        try {
            TarUtils.parseOctal(extendedBuffer, 0, 3);
            fail("Expected IllegalArgumentException for invalid octal digit");
        } catch (IllegalArgumentException e) {
            // Message contains error details via exceptionMessage helper
            assertTrue(e.getMessage().contains("128"));
        }
    }

    @Test
    public void testParseOctal_InvalidCharacters() {
        // "1a3"
        byte[] buffer = "1a3".getBytes();
        byte[] extendedBuffer = new byte[10];
        System.arraycopy(buffer, 0, extendedBuffer, 0, buffer.length);
        extendedBuffer[buffer.length + 1] = 0;

        try {
            TarUtils.parseOctal(extendedBuffer, 0, 3);
            fail("Expected IllegalArgumentException for non-digit character");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("1a3"));
        }
    }

    @Test
    public void testParseOctal_LargeOctal() {
        // "7777777777"
        byte[] buffer = "7777777777".getBytes();
        byte[] extendedBuffer = new byte[20];
        System.arraycopy(buffer, 0, extendedBuffer, 0, buffer.length);
        extendedBuffer[buffer.length + 1] = 0;

        long expected = Long.parseLong("7777777777", 8);
        assertEquals(expected, TarUtils.parseOctal(extendedBuffer, 0, 10));
    }

    @Test
    public void testParseOctal_OffsetUsage() {
        // "   755" but start at index 3
        byte[] buffer = "   755".getBytes();
        byte[] extendedBuffer = new byte[15];
        System.arraycopy(buffer, 0, extendedBuffer, 0, buffer.length);
        extendedBuffer[buffer.length + 1] = 0;

        // offset 3, length 3 -> "755"
        assertEquals(493L, TarUtils.parseOctal(extendedBuffer, 3, 3));
    }

    @Test
    public void testParseOctal_TrimmingLogicBranch() {
        // Testing the while loop for trailer: trailer == 0 || trailer == ' '
        // buffer: [7, 5, 5, ' ', ' ', 0, 0] 
        // length: 5 (the "755  ")
        // end + 1 will be index 6. buffer[6] is 0.
        byte[] buffer = {'7', '5', '5', ' ', ' ', 0, 0, 0};
        assertEquals(493L, TarUtils.parseOctal(buffer, 0, 5));
    }
}
